// Bundled materials allow downloads when the deck is opened directly as a local file.
const seminarMaterials={"assets/img/work-house-before-v2.png":"","assets/img/work-product.png":""};
document.querySelectorAll('.iw-download').forEach(link=>{
  const encoded=seminarMaterials[link.getAttribute('href')];
  if(!encoded) return;
  link.addEventListener('click',event=>{
    event.preventDefault();
    const binary=atob(encoded);
    const bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));
    const url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));
    const download=document.createElement('a');
    download.href=url;
    download.download=link.download;
    document.body.append(download);
    download.click();
    download.remove();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
  });
});